steps.analogousExample:
/* Example: a fade-in animation */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Example: applying animation to elements */
div {
  animation: slide 2s ease-in-out infinite;
}

/* Example: using animation-fill-mode */
div {
  animation-fill-mode: forwards;
}

/* Example: applying different fill-mode values to elements */
div:nth-child(1) {
  animation-fill-mode: none;
}
div:nth-child(2) {
  animation-fill-mode: forwards;
}
div:nth-child(3) {
  animation-fill-mode: both;
}

/* Example: adding direction to an animation rule */
div {
  animation-direction: normal;
}

/* Example of targeting specific elements with different direction values */
div:nth-child(2) {
  animation-direction: reverse;
}
div:nth-child(3) {
  animation-direction: alternate;
}

/* Example: combining two animation properties */
div.special {
  animation-fill-mode: both;
  animation-direction: alternate;
}

/* Similar: adding animation-delay to an element */
.element {
  animation-delay: 1s;
}

steps.seedCode:
body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  padding: 20px;
}

div {
  width: 100px;
  height: 100px;
  background-color: #3498db;
  border-radius: 8px;
  animation-name: slide;
  animation-duration: 2s;
  animation-fill-mode: forwards;
  animation-direction: normal;
}

@keyframes slide {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(200px);
  }
}

/* First div: fill-mode forwards */
div:nth-child(1) {
  animation-fill-mode: forwards;
}

/* Second div: fill-mode backwards */
div:nth-child(2) {
  animation-fill-mode: backwards;
}

/* Third div: direction alternate */
div:nth-child(3) {
  animation-direction: alternate;
}

/* Fourth div: combine both properties */
div:nth-child(4) {
  animation-fill-mode: backwards;
  animation-direction: reverse;
  /* Add animation-delay here */
}

